//! Reversible string encoding with a generated byte lookup decoder. No dynamic compilation or byte-to-character primitive.
use crate::lexer::{Kind, Token};
use crate::renamer::fresh_identifier;
use rand::{Rng, RngCore};
use std::collections::HashSet;

pub fn decode_literal(s: &str) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    let first = *b.first()?;
    if first == b'[' {
        let mut j = 1;
        while b.get(j) == Some(&b'=') {
            j += 1
        }
        if b.get(j) != Some(&b'[') {
            return None;
        }
        let eq = j - 1;
        let close = format!("]{}]", "=".repeat(eq));
        if !s.ends_with(&close) {
            return None;
        }
        let content = &s[j + 1..s.len() - close.len()];
        return Some(
            content
                .strip_prefix('\n')
                .unwrap_or(content)
                .as_bytes()
                .to_vec(),
        );
    }
    if (first != b'\'' && first != b'\"') || b.last() != Some(&first) {
        return None;
    }
    let mut it = s[1..s.len() - 1].chars().peekable();
    let mut out = Vec::new();
    while let Some(c) = it.next() {
        if c != '\\' {
            let mut buf = [0; 4];
            out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            continue;
        }
        let e = it.next()?;
        match e {
            'a' => out.push(7),
            'b' => out.push(8),
            'f' => out.push(12),
            'n' => out.push(10),
            'r' => out.push(13),
            't' => out.push(9),
            'v' => out.push(11),
            '\\' => out.push(92),
            '\'' => out.push(39),
            '\"' => out.push(34),
            '\n' => out.push(10),
            '\r' => {
                if it.peek() == Some(&'\n') {
                    it.next();
                }
                out.push(10)
            }
            'z' => {
                while it.peek().is_some_and(|x| x.is_whitespace()) {
                    it.next();
                }
            }
            'x' => {
                let a = it.next()?.to_digit(16)?;
                let b = it.next()?.to_digit(16)?;
                out.push((a * 16 + b) as u8)
            }
            'u' => {
                if it.next()? != '{' {
                    return None;
                }
                let mut n = 0u32;
                let mut any = false;
                while it.peek() != Some(&'}') {
                    n = n.checked_mul(16)?.checked_add(it.next()?.to_digit(16)?)?;
                    any = true
                }
                it.next();
                if !any {
                    return None;
                }
                let c = char::from_u32(n)?;
                let mut buf = [0; 4];
                out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes())
            }
            '0'..='9' => {
                let mut n = e.to_digit(10)?;
                for _ in 0..2 {
                    if it.peek().is_some_and(|x| x.is_ascii_digit()) {
                        n = n * 10 + it.next()?.to_digit(10)?
                    } else {
                        break;
                    }
                }
                if n > 255 {
                    return None;
                }
                out.push(n as u8)
            }
            other => {
                let mut buf = [0; 4];
                out.extend_from_slice(other.encode_utf8(&mut buf).as_bytes())
            }
        }
    }
    Some(out)
}
/// Whether `text` can be the final token of an expression, which makes a following literal call sugar.
fn can_end_expression(text: &str) -> bool {
    match text {
        ")" | "]" | "}" => true,
        _ => {
            let first = text.as_bytes()[0];
            (first.is_ascii_alphanumeric() || first == b'_') && !is_keyword(text)
        }
    }
}

fn is_keyword(text: &str) -> bool {
    matches!(
        text,
        "and"
            | "break"
            | "do"
            | "else"
            | "elseif"
            | "end"
            | "false"
            | "for"
            | "function"
            | "goto"
            | "if"
            | "in"
            | "local"
            | "nil"
            | "not"
            | "or"
            | "repeat"
            | "return"
            | "then"
            | "true"
            | "until"
            | "while"
    )
}

/// Encrypt each string with an additive byte key, and return one local decoder prefix.
pub fn transform(tokens: &mut Vec<Token>, rng: &mut impl RngCore) -> Result<(), String> {
    let mut used: HashSet<String> = tokens
        .iter()
        .filter(|t| t.kind == Kind::Ident)
        .map(|t| t.text.clone())
        .collect();
    let decoder = fresh_identifier(rng, &mut used);
    let sarg = fresh_identifier(rng, &mut used);
    let tab = fresh_identifier(rng, &mut used);
    let out = fresh_identifier(rng, &mut used);
    let idx = fresh_identifier(rng, &mut used);
    let key = rng.gen_range(1u16..=255) as u8;
    let mut changed = false;
    let mut rewritten = Vec::with_capacity(tokens.len());
    // A literal that directly follows an expression is Lua's call sugar (`print "x"`). Rewriting
    // it into a call expression would change the parse, so those literals are left untouched.
    let mut previous: Option<String> = None;
    for t in tokens.drain(..) {
        if t.kind == Kind::String {
            let sugar = previous.as_deref().is_some_and(can_end_expression);
            if !sugar {
                if let Some(bytes) = decode_literal(&t.text) {
                    let enc = bytes
                        .iter()
                        .map(|b| format!("\\{:03}", b.wrapping_add(key)))
                        .collect::<String>();
                    let repl = crate::lexer::lex(&format!("{}(\"{}\")", decoder, enc))?;
                    rewritten.extend(repl);
                    changed = true;
                    if !matches!(t.kind, Kind::Space | Kind::Comment) {
                        previous = Some(t.text.clone());
                    }
                    continue;
                }
            }
        }
        if !matches!(t.kind, Kind::Space | Kind::Comment) {
            previous = Some(t.text.clone());
        }
        rewritten.push(t)
    }
    *tokens = rewritten;
    if !changed {
        return Ok(());
    }
    let values = (0..=255)
        .map(|v| format!("\"\\{:03}\"", v))
        .collect::<Vec<_>>()
        .join(",");
    let prefix=format!("local function {decoder}({sarg}) local {tab}={{{values}}};local {out}={{}};for {idx}=1,#{sarg} do {out}[{idx}]={tab}[(string.byte({sarg},{idx})-{key})%256+1] end;return table.concat({out}) end;");
    let mut pre = crate::lexer::lex(&prefix)?;
    pre.extend(std::mem::take(tokens));
    *tokens = pre;
    Ok(())
}
